/** A module can scope construction terminology without changing peer dictionaries. */
export const TradeLabelContext = createContext<string | null>(null);
export function useT() {
  const lang = useCatalog((s) => s.lang);
  const tradeLabel = useContext(TradeLabelContext);
  return (k: TKey, vars?: Record<string, string | number>) => {
    let s = (k === "trade" ? tradeLabel : null) ?? roomUITranslation(lang, k) ?? dict[lang][k] ?? en[k];
    if (vars) for (const [a, b] of Object.entries(vars)) s = s.replace(`{${a}}`, String(b));
    return s;
  };
}
